models.tidalShock=p=>{const fn=b=>4/3*(H.G*10**p.mass/p.V)**2*p.r*p.r/b**4,E=fn(p.b),ratio=p.b*20/(p.V*p.r),focus=H.G*10**p.mass/(p.b*p.V*p.V),extent=p.r/p.b,warnings=[];if(ratio>=.3)warnings.push('遭遇不够快：需要绝热响应或动力学求解');if(focus>=.1)warnings.push('引力聚焦不可忽略，直线飞掠近似不可靠');if(extent>=.1)warnings.push('目标尺度与冲量参数的比值不够小，远距离潮汐展开需谨慎');return {curves:[series('远距离脉冲估算',gridAt(20,100,fn,[p.b]))],point:{x:p.b,y:E},xLabel:'冲量参数 b（kpc）',yLabel:'ΔE/M（km²/s²）',yLog:true,values:[E,Math.sqrt(2*E),ratio,focus],scene:{kind:'shock',radius:p.r,kick:2*H.G*10**p.mass/(p.V*p.b*p.b)},validation:warnings.length?{level:'caution',message:warnings.join('；')} :null,summary:(warnings.length?'当前仅作公式外推：'+warnings.join('；')+'。':'当前时标、弱偏转和远距离参考检查通过；仍只是一阶脉冲近似。')+' 聚焦参数χ=GMp/(bV²)，小尺度参考r_rms/b='+extent.toFixed(3)+'；0.1与0.3是网页的近似质量提示，不是精确物理分界。'};};
models.heatEnd=p=>{const fn=h=>1/(1-h),bound=p.h<1,limit=bound?Math.max(.95,p.h):.99,xs=grid(0,-Math.log1p(-limit),u=>0,201).map(d=>-Math.expm1(-d.x));return {curves:[series('假设同源终态',gridAt(0,limit,fn,[...xs,p.h]))],point:bound?{x:p.h,y:fn(p.h)}:undefined,xDomain:[0,Math.max(1.1,p.h)],xBands:[{from:1,to:Math.max(1.1,p.h),label:'无束缚终态'}],yLog:true,xLabel:'注能 ΔE / |Ei|',yLabel:'Rf / Ri（对数轴）',values:[bound?fn(p.h):'无束缚终态',bound?1-p.h:'无束缚终态',1+p.h],validation:!bound?{level:'limit',message:'总能量非负：这些附加假设不给出有限束缚终态。'}:null,summary:'初始与终态均维里平衡、同源、质量不损失且无外部能量交换。曲线在h→1⁻时发散，不跨过极点连接到负半径。曲线只给假设终态，不演示弛豫；注能后即时动能增加，重新平衡后的动能却可能降低。'};};
models.tidalRadius=p=>{const q=10**p.q,fn=log=>p.R*Math.cbrt(10**log/(3+10**log)),exact=fn(p.q),approx=p.R*Math.cbrt(q/3);return {curves:[series('圆轨道点质量宿主',grid(-4,-1,fn))],point:{x:p.q,y:exact},xLabel:'log₁₀ 质量比 m/M',yLabel:'潮汐尺度 rt（kpc）',values:[exact,exact/p.R,100*(approx/exact-1)],scene:{kind:'tidalBoundary',ratio:exact/p.R},summary:'圆轨道点质量宿主的理想潮汐尺度，q≪1时回到Hill近似。球形截断不是严格逃逸面，超过该半径的物质不等于立即全部被剥离。'};};
function dragBracket(X){if(X<.3)return 4/Math.sqrt(Math.PI)*(X**3/3-X**5/5+X**7/14-X**9/54+X**11/264);return 1-H.erfc(X)-2*X*Math.exp(-X*X)/Math.sqrt(Math.PI);}
models.drag=p=>{const M=10**p.mass,rho=10**p.rho,fn=X=>X===0?0:4*Math.PI*H.G**2*M*rho*3*dragBracket(X)/(2*p.sigma*p.sigma*X*X)/conv,a=fn(p.X),v=Math.SQRT2*p.sigma*p.X;return {curves:[series('Maxwell背景阻力加速度大小',grid(0,4,fn))],point:{x:p.X,y:a},xLabel:'X = v / (√2 σ)',yLabel:'|aDF|（km/s/Gyr）',values:[a,p.X===0?'零速极限':v/a,dragBracket(p.X)],summary:'均匀、各向同性Maxwell背景，lnΛ=3，重试验体远大于背景粒子。力与速度反向；本图不生成真实自洽尾迹，也不描述有核或强非均匀宿主的全部摩擦。'};};
models.friction=p=>{const M=10**p.mass,tdf=1.17*p.R*p.R*200/(H.G*M*3)*conv,fn=t=>p.R*Math.sqrt(Math.max(0,1-t)),radius=fn(p.tau),q0=H.G*M/(200*200*p.R),q=radius>0?H.G*M/(200*200*radius):'理想端点不定义',caution=typeof q==='number'&&q>.1;return {curves:[series('固定质量圆轨道衰减',gridAt(0,1,fn,[p.tau]))],point:{x:p.tau,y:radius},xLabel:'t / tDF',yLabel:'轨道半径（kpc）',values:[tdf,radius,q],scene:{kind:'encounter',separation:.55*Math.sqrt(Math.max(0,1-p.tau)),rt:.12},validation:caution?{level:'caution',message:'当前卫星不再远轻于轨道内部宿主，圆轨道轻卫星衰减只作外推。'}:radius===0?{level:'limit',message:'理想吸收端点：中心宿主包围质量趋零，此处质量比不定义。'}:null,summary:(caution?'当前卫星/内部宿主质量比='+q.toFixed(3)+'，轻卫星近似不可靠；下列时标只作公式外推。 ':'')+'质量比使用当前r(t)，初始比为'+q0.toFixed(3)+'。奇异等温宿主Vc=200km/s、lnΛ=3、圆轨道且卫星不失质量。t/tDF=1是理想吸收端点；潮汐失质量、核结构和大质量比会破坏近似。'};};
models.ram=p=>{const unit=P.Msun/P.pc**2,rest=2*Math.PI*P.G*500*50*unit*unit,pr=P.mp*10**p.n*(p.V*1e5)**2,r=pr===0?Infinity:Math.max(0,Math.log(rest/pr)/(1/3+1/5)),x=r/5,f=Number.isFinite(r)?1-Math.exp(-x)*(1+x):1;return {curves:[series('盘恢复压力',grid(0,30,R=>rest*Math.exp(-R/3-R/5))),series('冲压压力',grid(0,30,()=>pr))],point:Number.isFinite(r)?{x:r,y:pr}:undefined,xLabel:'盘半径（kpc）',yLabel:'压力（dyn/cm²）',yLog:true,values:[pr/rest,Number.isFinite(r)?r:'无有限边界',f*100],scene:{kind:'disk',Rd:5,radius:Number.isFinite(r)?r:20},summary:'恒星/气体中心面密度500/50M☉pc⁻²，尺度3/5kpc；垂直薄盘冲压比较，未模拟实际剥离速度、倾角、压缩或后续淬火。剩余气体由指数盘面积积分得到。'};};
models.starvation=p=>{const a=(.6+p.loading)/p.dep,gas=t=>Math.exp(-a*t),rem=gas(p.time),star=.6/(.6+p.loading)*(1-rem),out=p.loading/(.6+p.loading)*(1-rem);return {curves:[series('冷气体份额',grid(0,10,gas)),series('锁定恒星份额',grid(0,10,t=>.6/(.6+p.loading)*(1-gas(t))))],point:{x:p.time,y:rem},xLabel:'补给切断后 t（Gyr）',yLabel:'质量 / 初始冷气体',values:[10*rem/p.dep,star*100,out*100],scene:{kind:'reservoir',fraction:star,outflow:out},summary:'初始冷气体10¹⁰M☉、回流R=0.4、Ψ=Mcold/tdep，切断新补给并保留井混合外流。指数耗尽说明延迟效应，不证明所有红卫星都经历同一种机制。'};};
models.spheroid=p=>{const i=p.i*Math.PI/180,q=Math.sqrt(Math.cos(i)**2+p.q0*p.q0*Math.sin(i)**2),I0=1e10/(2*Math.PI*3000**2*q);return {curves:[series('投影长轴上的高斯光度',grid(0,10,R=>I0*Math.exp(-R*R/18)))],xLabel:'投影长轴半径（kpc）',yLabel:'I（L☉/pc²）',values:[q,I0,1-q],scene:{kind:'ellipse',q},summary:'轴对称扁球高斯模型，a=3kpc、总L=10¹⁰L☉，qapp²=cos²i+q0²sin²i。改变投影不改变总光；高斯是解析教学延伸，不是实际Sérsic拟合或三维形状的唯一反演。'};};
models.anisotropy=p=>{const vc=b=>p.sigma*Math.sqrt((p.gamma-2*b)/(1-b*(p.gamma-1)/p.gamma)),V=vc(p.beta),sr=V/Math.sqrt(p.gamma-2*p.beta),ref=Math.sqrt(3)*p.sigma,exactGamma3=Math.abs(p.gamma-3)<1e-9;return {curves:[series('当前 γ：固定 σlos 所需的 Vc',grid(-.5,.5,vc)),series('γ=3 参考：Vc=√3 σlos（与 β 无关）',grid(-.5,.5,()=>ref))],point:{x:p.beta,y:V},xLabel:'轨道各向异性 β',yLabel:'Vc（km/s）',values:[V,sr,V*V*10/H.G],validation:exactGamma3?{level:'note',message:'γ=3：投影恰好抵消 β 依赖，Vc=√3 σlos 与 β 无关，这一模型下的质量估计也不依赖 β。但单一 σlos 仍不能同时确定 β 与 σr（σr=Vc/√(γ−2β) 随 β 改变）；若 γ 也未知，另有简并。'}:null,summary:'固定可观测的视向弥散 σlos，对每个 β 由投影二阶矩反解所需的 Vc；与第 5 章固定三维 σr 的实验相反，两种约束不能互换。虚线是 γ=3 参考：投影抵消后 Vc=√3 σlos 与 β 无关，这一模型下的质量估计也不依赖 β，但 σr 仍随 β 改变。对数球势、常 β 与常 σr、无限尺度无关标记分布，γ>max(1,2β)；二阶矩解不保证完整分布函数非负。'};};
models.bhResolution=p=>{const r=Gpc*10**p.mass/(p.sigma*p.sigma),angle=D=>.206265*r/D;return {curves:[series('影响半径的角尺度',grid(5,200,angle))],point:{x:p.D,y:angle(p.D)},xLabel:'距离（Mpc）',yLabel:'角半径（角秒）',yLog:true,values:[r,angle(p.D),angle(p.D)/p.res],summary:'rBH=GMBH/σ²，距离采用低红移欧氏角换算。分辨影响半径只是质量测量的重要条件之一，PSF、谱线质量与轨道结构仍会影响推断。'};};
models.dryMerger=p=>{const f=q=>(1+q)**2/(1+q*q/p.size),r=f(p.q),v2=(1+p.q*p.q/p.size)/(1+p.q);return {curves:[series('同源抛物线干并合终态',grid(.02,1,f))],point:{x:p.q,y:r},xLabel:'卫星/主星系质量比 q',yLabel:'Rf / R₁',values:[r,Math.sqrt(v2),1+p.q],summary:'无气体、无质量流失、同结构系数、抛物线零轨道能，且不向暗晕输运额外能量。只比较能量守恒终态，未计算并合时间或真实弛豫。'};};
models.fplane=p=>{const a=2/(1+2*p.delta),b=-(1+p.delta)/(1+2*p.delta),fn=sigma=>5*(sigma/200)**a*(p.I/300)**b;return {curves:[series('同源M/L倾斜例子',grid(100,350,fn))],point:{x:p.sigma,y:fn(p.sigma)},xLabel:'σ（km/s）',yLabel:'Re（kpc；指定归一化）',values:[a,b,fn(p.sigma)],summary:'令M/L∝L^δ、L=2πIe Re²，与维里同源关系组合；5kpc归一化人为指定。基本平面倾斜也可来自结构、暗物质比例等，不能唯一归因于星族M/L。'};};
models.phaseProxy=p=>{const rho=10**p.rho,fn=sigma=>rho/sigma**3,Q=fn(p.sigma),ref=1e-5;return {curves:[series('ρ/σ³ 代理',grid(50,300,fn)),series('指定初态参照',grid(50,300,()=>ref))],point:{x:p.sigma,y:Q},xLabel:'σ（km/s）',yLabel:'代理密度（M☉ pc⁻³ (km/s)⁻³）',yLog:true,values:[Q,Q/ref,ref*p.sigma**3],summary:'ρ/σ³只是相空间密度代理，参照10⁻⁵人为指定，不等于已知分布函数的精确fmax。无碰撞混合约束针对细/粗粒化分布，代理比值不能独自证明或反驳具体形成通道。'};};
models.frosting=p=>{const light=f=>f*p.contrast/(1-f+f*p.contrast),fL=light(p.f),tm=(1-p.f)*10+p.f*p.young,tl=(1-fL)*10+fL*p.young;return {curves:[series('年轻族群光度份额',grid(0,.2,f=>100*light(f)))],point:{x:p.f,y:100*fL},xLabel:'年轻族群质量份额',yLabel:'年轻族群光度份额（%）',values:[100*fL,tm,tl],scene:{kind:'frosting',mass:p.f,light:fL},summary:'老族群10Gyr、年轻族群年龄与单位质量光度比显式输入。光度加权平均不是由谱线拟合得到的SSP等效年龄，颜色也不能直接线性平均星等。'};};
const sigmaSB=5.670374419e-5;
function eddington(M){return 4*Math.PI*P.G*M*P.Msun*P.mp*P.c/P.sigmaT;}
models.eddington=p=>{const M=10**p.mass,LE=eddington(M),L=p.lambda*LE;return {curves:[series('指定Eddington比的光度',grid(0,2,l=>l*LE))],point:{x:p.lambda,y:L},xLabel:'L / LEdd',yLabel:'L（erg/s）',values:[LE,L/(p.eps*P.c*P.c)/P.Msun*P.yr,2*P.G*M*P.Msun/P.c**2/P.pc],scene:{kind:'nucleus'},summary:'纯氢电子散射、球对称各向同性稳态参照。Ṁin=L/(εc²)是供应率，黑洞保留增长还乘(1−ε)；Eddington光度不是任意几何流动的绝对硬上限。'};};
function diskFlux(M,mdot,Rin,x){if(x<=1)return 0;const r=Rin*x;return 3*P.G*M*mdot/(8*Math.PI*r**3)*(1-1/Math.sqrt(x));}
models.thinDisk=p=>{const M=10**p.mass*P.Msun,mdot=p.mdot*P.Msun/P.yr,rs=2*P.G*M/P.c**2,Rin=p.rin*rs,T=x=>(diskFlux(M,mdot,Rin,x)/sigmaSB)**.25,L=P.G*M*mdot/(2*Rin);return {curves:[series('单面通量对应的有效温度',gridAt(1,40,T,[49/36],321))],xLabel:'R / Rin',yLabel:'Teff（K）',values:[T(49/36),L,4*p.rin],scene:{kind:'nucleus'},summary:(L/eddington(10**p.mass)>1?'当前L/LEdd='+ (L/eddington(10**p.mass)).toFixed(2)+'，该参数组合不应视为可靠的薄盘预报。 ':'')+`两面总光度按式14.14直接积分为GMṀ/(2Rin)，半光半径4Rin；这是对原书附近文字内部矛盾的独立积分修正，并非列于作者勘误。Newtonian效率为${(1/(4*p.rin)).toFixed(4)}，不含GR、自旋或色修正。`};};
function jet(beta,theta){const a=theta*Math.PI/180,gamma=1/Math.sqrt(1-beta*beta),delay=1-beta*Math.cos(a);return {gamma,delay,app:beta*Math.sin(a)/delay,doppler:1/(gamma*delay)};}
models.superluminal=p=>{const v=jet(p.beta,p.angle);return {curves:[series('到达时间差给出的横向表观速度',gridAt(0,90,t=>jet(p.beta,t).app,[Math.acos(p.beta)*180/Math.PI,p.angle],321))],point:{x:p.angle,y:v.app},xLabel:'视线夹角（度）',yLabel:'vapp / c',values:[v.app,v.delay,v.gamma],summary:'相对论到达时间几何：Δtarrival=Δtemit(1−βcosθ)。物质速度仍小于c；这里不含宇宙红移，观测时间还需乘(1+z)。'};};
models.beaming=p=>{const v=jet(p.beta,p.angle),boost=t=>jet(p.beta,t).doppler**(3+p.alpha),a=p.angle*Math.PI/180,ratio=((1+p.beta*Math.cos(a))/(1-p.beta*Math.cos(a)))**(3+p.alpha);return {curves:[series('离散团块指定谱指数增亮',grid(0,90,boost))],point:{x:p.angle,y:boost(p.angle)},xLabel:'视线夹角（度）',yLabel:'Fν/F′ν（指定幂律）',yLog:true,values:[v.doppler,boost(p.angle),ratio],summary:'F′ν∝ν⁻ᵅ，离散团块采用D^(3+α)，稳态连续流的几何指数不同。与表观超光速的几何时钟分开；未模拟喷流产生或辐射输运。'};};
models.reverb=p=>{const sec=p.lag*86400,r=P.c*sec,Mvir=r*(p.v*1e5)**2/P.G/P.Msun,data=[{x:-.1*p.lag,y:0},{x:0,y:0},{x:0,y:1/(2*p.lag)},{x:2*p.lag,y:1/(2*p.lag)},{x:2*p.lag,y:0},{x:2.2*p.lag,y:0}];return {curves:[series('理想薄球壳响应（单位面积）',data)],xLabel:'观测延迟（天；无红移）',yLabel:'响应密度 / 天⁻¹',values:[r/P.pc,Mvir,p.factor*Mvir],summary:'薄球壳响应是新增理想几何，延迟0–2r/c、平均r/c。M=f cτ Δv²/G依赖线宽约定和几何f；曲线不是实际光变观测或完整速度—延迟图。'};};
models.bhGrowth=p=>{const tE=P.sigmaT*P.c/(4*Math.PI*P.G*P.mp)/P.Gyr,rate=(1-p.eps)*p.lambda*p.duty/(p.eps*tE),fn=t=>p.seed+rate*t/Math.LN10,mass=10**fn(p.time);return {curves:[series('保留质量的无限燃料解析外推',grid(0,1,fn))],point:{x:p.time,y:fn(p.time)},xLabel:'增长持续时间（Gyr）',yLabel:'log₁₀ MBH / M☉',values:[1000/rate,mass,rate*p.time],scene:{kind:'nucleus'},summary:'恒定Eddington比、效率和占空比，dMBH/dt=(1−ε)Ṁin。显式计入辐射质量损失；不含燃料上限、角动量输运、反馈或种子形成，巨大外推质量不代表物理上能够实现。'};};
models.torus=p=>{const fn=a=>100*(1-Math.cos(a*Math.PI/180)),visible=p.i<p.opening;return {curves:[series('各向同性取向的未遮蔽概率',grid(0,90,fn))],point:{x:p.opening,y:fn(p.opening)},xLabel:'极轴起算的半张角（度）',yLabel:'未遮蔽比例（%）',values:[fn(p.opening),p.i,p.i===p.opening?'理想边界':visible?'广线视线可见':'广线视线被遮蔽'],scene:{kind:'torus',opening:p.opening,inclination:p.i},summary:'不透明轴对称环带的几何统一模型，随机方向均匀于cos i而不是i。取向无法解释全部AGN分类、射电响度或吸积状态；这里未求光谱辐射转移。'};};
models.agnFeedback=p=>{const cK=P.c/1e5,fn=sig=>p.coupling*p.eps*p.q*(cK/sig)**2,available=p.eps*p.q*(cK/p.sigma)**2;return {curves:[series('耦合能量 / 指定束缚标度',grid(100,350,fn))],point:{x:p.sigma,y:fn(p.sigma)},xLabel:'星系 σ（km/s）',yLabel:'\\(E_{\\rm coupled}/(M_{\\rm gal}\\sigma^2)\\)',values:[available,fn(p.sigma),1/available],summary:'以Mgalσ²作束缚能标度，q=MBH/Mgal，\\(\\epsilon\\)是相对\\(M_{\\rm BH}c^2\\)的预算效率，不是增长模型的供给质量辐射效率；耦合率另计。能量足够是预算层面的线索，不保证气体必然逃逸、淬火或均匀吸收。'};};

function lfDex(x,alpha){const t=10**x;return Math.LN10*t**(alpha+1)*Math.exp(-t);}
models.luminosity=p=>{const phi=.003,L=10**p.Lstar,fn=x=>phi*lfDex(x,p.alpha),number=simpson(fn,-3,1.5,1024),light=L*simpson(x=>10**x*fn(x),-3,1.5,1024);return {curves:[series('每dex数量密度',grid(-3,1,fn))],xLabel:'log₁₀ L/L*',yLabel:'φdex（Mpc⁻³ dex⁻¹）',yLog:true,values:[number,light,100*L*simpson(x=>10**x*fn(x),-3,-1,512)/light],summary:'Schechter函数按dlog₁₀L展示，φ*=0.003Mpc⁻³；数量与光度积分都限定0.001–31.6L*，曲线显示至10L*。当α≤−1时，不能把有限下限所得数量宣称为收敛的无限总数。'};};
models.counts=p=>{const fn=m=>100*p.density*p.light**1.5*10**(.6*(m-20));return {curves:[series('Euclidean无演化计数',grid(16,24,fn))],point:{x:p.mag,y:fn(p.mag)},xLabel:'极限星等 m',yLabel:'N(<m)（指定归一化；sr⁻¹）',yLog:true,values:[fn(p.mag),10**.6,p.density*p.light**1.5],summary:'均匀Euclidean、固定光度族群、无K修正或演化；m=20参考计数100sr⁻¹人为指定。密度B与光度A以BA^(3/2)进入计数，单一计数不能唯一反演形成历史。'};};
function matching(alpha){const n=4001,lo=6,hi=11.5,dx=(hi-lo)/(n-1),xs=grid(lo,hi,x=>lfDex(x-10,alpha),n),cum=Array(n).fill(0);for(let i=n-2;i>=0;i--)cum[i]=cum[i+1]+dx*(xs[i].y+xs[i+1].y)/2;const total=cum[0];function inverse(rank){const target=rank*total;let l=0,r=n-1;while(r-l>1){const m=(l+r)>>1;if(cum[m]>target)l=m;else r=m;}const t=(cum[l]-target)/(cum[l]-cum[r]||1);return lo+(l+t)*dx;}const rank=x=>(10**(-.9*(x-10))-10**(-4.5))/(1-10**(-4.5));return {rank,lum:x=>10**inverse(rank(x)),total};}
models.matching=p=>{const m=matching(p.alpha),M=10**p.mass,L=m.lum(p.mass),eff=p.upsilon*L/(.16*M);return {curves:[series('等累计数量的单调匹配',grid(10,15,x=>Math.log10(m.lum(x))))],point:{x:p.mass,y:Math.log10(L)},xLabel:'log₁₀ Mhalo / M☉',yLabel:'log₁₀ L / L☉',values:[L,eff,m.rank(p.mass)],summary:(eff>1?'当前恒星效率超过1，指定M/L和两端分布违反重子预算，应判为无效组合。':'效率按M*=ΥL、fb=0.16计算。')+' 暗晕每dex∝M⁻⁰·⁹与有限Schechter光度函数分别归一到相同数量；每个独立晕一个星系，无散布、无卫星，非观测拟合。'};};
models.central=p=>{const fn=x=>1e10*(10**(x-12))**p.beta/(1+(10**(x-12))**(p.beta-p.gamma)),X=10**(p.mass-12),slope=p.beta-(p.beta-p.gamma)*X**(p.beta-p.gamma)/(1+X**(p.beta-p.gamma));return {curves:[series('指定中心星系 Lc(M)',grid(10,15,fn))],point:{x:p.mass,y:fn(p.mass)},xLabel:'log₁₀ Mhalo / M☉',yLabel:'中心 Lc（L☉）',yLog:true,values:[fn(p.mass),slope,X],summary:'Lc=L₀X^β/(1+X^(β−γ))，L₀=10¹⁰L☉、ML=10¹²M☉。低/高质量斜率分别趋于β/γ；这里只指定中心关系，不假定卫星条件分布也归一为1。'};};
models.cosmicSFR=p=>{const epoch=(1+p.z)**2*Math.exp(-p.z/3),fn=x=>x<p.cut?0:.003*(10**(x-12))**(-.9)*Math.exp(-(10**x)/(1e14*Math.exp(-p.z)))*p.eff*10**(x-12)*Math.exp(-(10**(x-12.5)))*epoch,total=simpson(fn,p.cut,15,1024),peakX=Math.max(p.cut,Math.min(15,Math.log10(.1/(1/(1e14*Math.exp(-p.z))+1/10**12.5)))),data=gridAt(8,15,fn,[p.cut,peakX],281),peak={x:peakX,y:fn(peakX)};if(p.cut>8){const at=data.findIndex(d=>d.x===p.cut);data.splice(at,0,{x:p.cut,y:0});}return {curves:[series('指定中心形成率的每dex贡献',data)],xLabel:'log₁₀ Mhalo / M☉',yLabel:'dρSFR/dlogM（M☉ yr⁻¹ Mpc⁻³）',values:[total,total>0?peak.x:"无星形成",epoch],summary:'正的玩具暗晕质量函数与指定SFR相乘，只在质量下限至10¹⁵M☉积分。阈值处画垂直跳变，不将阈值以下插值为非零；贡献峰由该指定函数的导数求得并加入绘图。红移因子与高质量截止人为设定；只统计中心，不宣称真实卫星均无星形成或宇宙峰值由此唯一决定。'};};
models.environment=p=>{const f=w=>.2*(1-w)+.8*w,matched=f(.5);return {curves:[series('改变高质量晕混合比例',grid(0,1,f)),series('同质量组成对照',grid(0,1,()=>matched))],point:{x:p.w,y:f(p.w)},xLabel:'高质量晕占比 w',yLabel:'红色比例（合成样本）',values:[100*f(p.w),100*matched,100*(f(p.w)-matched)],summary:'低/高质量晕内部红色概率固定0.2/0.8；只改变混合组成就能产生环境相关。同质量对照w=0.5人为指定，示例不证明真实环境没有直接作用，也不是SDSS测量。'};};
models.occupation=p=>{const prob=[p.scatter/2,0,1-p.scatter,0,p.scatter/2],mean=2,F2=2+4*p.scatter;return {curves:[series('合成 P(N|M)',prob.map((y,x)=>({x,y})))],xLabel:'同一暗晕中的星系数 N',yLabel:'概率 P(N|M)',discrete:true,values:[mean,F2/2,F2+mean-mean*mean],summary:'在恒定N=2和各半概率N=0/4之间混合，始终⟨N⟩=2；每晕平均星系对数量=⟨N(N−1)⟩/2，不含自配对且每一对只计一次。该合成分布不指定中心/卫星条件关系，也不是Poisson采样。'};};
models.bias=p=>{const density=[.01,.001,.00005],bias=[.8,1.5,3],N=[p.low,p.mid,p.high],weights=N.map((v,i)=>v*density[i]),ng=weights.reduce((a,b)=>a+b,0),b=ng?weights.reduce((s,v,i)=>s+v*bias[i],0)/ng:0;return {curves:[series('各质量箱对数量的贡献',weights.map((y,i)=>({x:11+2*i,y})))],xLabel:'合成暗晕 log₁₀ M / M☉',yLabel:'\\(n_i\\langle N_i\\rangle\\)（Mpc⁻³）',discrete:true,values:[ng,ng?b:'无星系样本',ng?b*b:'无适用相关比'],summary:'三箱n=(0.01,0.001,0.00005)Mpc⁻³、bh=(0.8,1.5,3)明确指定。bg=ΣnNbh/ΣnN，仅在线性大尺度确定性极限有ξgg=bg²ξm；无星系时不定义偏倚。'};};
function equilibrium(n,T,Gamma,C=1){const alpha=5e-13*(T/1e4)**(-.7),a=alpha*C*n,x=Gamma===0?1:2*a/(Gamma+2*a+Math.sqrt(Gamma*Gamma+4*Gamma*a));return {x,alpha,trec:1/(alpha*C*n)};}
models.transmission=p=>{const tau=10**p.tau,cover=p.cover,mean=(1-cover)*Math.exp(-.1)+cover*Math.exp(-tau),effective=-Math.log(mean),average=.1*(1-cover)+tau*cover;return {curves:[series('可调单元透射',grid(-2,2,x=>Math.exp(-(10**x)))),series('混合视线平均透射',grid(-2,2,x=>(1-cover)*Math.exp(-.1)+cover*Math.exp(-(10**x))))],point:{x:p.tau,y:Math.exp(-tau)},xLabel:'log₁₀ 光学深度 τ',yLabel:'\\(F/F_{\\rm cont}\\)',values:[Math.exp(-tau),effective,average],summary:'两类合成视线单元：比例f有可调τ，其余τ=0.1；调整f会同时改变平均透射曲线与τeff。τeff=−ln⟨exp(−τ)⟩≤⟨τ⟩；黑槽可由很大的共振光深造成，不等价于中性氢份额为1，也未直接反演全球再电离史。'};};
models.photo=p=>{const n=10**p.n,Gamma=10**p.Gamma,v=equilibrium(n,p.T,Gamma,p.C),fn=lg=>equilibrium(n,p.T,10**lg,p.C).x;return {curves:[series('纯氢光电离平衡中性比例',grid(-16,-10,fn))],point:{x:p.Gamma,y:v.x},xLabel:'log₁₀ Γphoto / s⁻¹',yLabel:'中性份额 xHI',yLog:true,values:[v.x,1/Gamma/P.Myr,v.trec/P.Myr],summary:'Γx=α CnH(1−x)²，α=5×10⁻¹³(T/10⁴K)⁻⁰·⁷cm³/s，稳定求根保证0≤x≤1。C是有效团块因子，不是电离填充率；忽略碰撞电离、屏蔽、He和辐射输运。'};};
function ionBubble(Q,n,C,t,off){const alpha=2.6e-13,trec=1/(alpha*C*n),RS=Math.cbrt(3*Q/(4*Math.PI*alpha*C*n*n)),v=t<=off?-Math.expm1(-t):(-Math.expm1(-off))*Math.exp(-(t-off));return {RS,trec,r:RS*Math.cbrt(Math.max(0,v)),volumeFraction:v};}
models.ionBubble=p=>{const Q=10**p.Q,n=10**p.n,v=ionBubble(Q,n,p.C,p.time,p.off),fn=t=>ionBubble(Q,n,p.C,t,p.off).r/(1e6*P.pc),ratio=p.time===0?0:v.r/(P.c*p.time*v.trec);return {curves:[series('开灯后增长与关灯后复合',gridAt(0,5,fn,earlyGrid(5,[p.off,p.time])))],point:{x:p.time,y:fn(p.time)},xLabel:'t / trec',yLabel:'电离半径（Mpc）',values:[fn(p.time),v.trec/P.Myr,p.time===0?'初始零半径':ratio],scene:{kind:'bubble',fraction:v.r/v.RS,equivalent:true},summary:(ratio>1?'当前R>ct，非相对论前沿外推已超出有效域。':'')+' 静态均匀纯氢、case-B α=2.6×10⁻¹³。关灯后的指数项只作“完全电离锐边界等效体积”的线性闭合，不是局部真实复合或因果前沿回缩；固定体元自由复合应为xe=1/(1+Δt/trec)。未含有限光速、宇宙膨胀和流体膨胀；单泡不预测全球拓扑。'};};
models.spin21=p=>{const cmb=2.7255*(1+p.z),amp=28*Math.sqrt((1+p.z)/10)*p.x,tau=Ts=>amp*.001*(1+p.z)/Ts,thin=Ts=>amp*(1-cmb/Ts),fn=Ts=>1000*(Ts-cmb)/(1+p.z)*(-Math.expm1(-tau(Ts))),Ts=(cmb+p.y*p.T)/(1+p.y);return {curves:[series('有限光深21cm亮温差',grid(2,300,fn)),series('光学薄近似对照',grid(2,300,thin))],point:{x:Ts,y:fn(Ts)},xLabel:'自旋温度 Ts（K）',yLabel:'δTb（mK）',values:[Ts,fn(Ts),1420.405751/(1+p.z)],summary:'由原书式16.83保留1−exp(−τ)，τ由式16.84的28mK高红移归一化推得；冷气体不强行采用光学薄极限。均匀、Ωbh=0.03、Ωm=0.3，忽略速度梯度。采用书中y形式Ts=(TCMB+yTK)/(1+y)，合并碰撞与Lyα耦合且Tα=TK；耦合强度为指定输入。当前τ21='+tau(Ts).toFixed(4)+'。'};};
function absorptionLine(N,T,turb){const b=Math.sqrt(2*P.k*T/P.mp/1e10+turb*turb),tau=N/2.6e13*20/b,flux=v=>Math.exp(-tau*Math.exp(-((v/b)**2))),W=1215.67/(P.c/1e5)*simpson(v=>1-flux(v),-12*b,12*b,2048);return {b,tau,flux,W};}
models.line=p=>{const v=absorptionLine(10**p.N,p.T,p.turb);return {curves:[series('仅Doppler高斯光深的透射',grid(-160,160,v.flux,401))],xLabel:'相对线心速度（km/s）',yLabel:'归一化透射 F',values:[v.b,v.tau,v.W],summary:'b²=2kBT/mp+bturb²；Lyα τ₀≈(N/2.6×10¹³)(20/b)。Wrest=(λα/c)∫(1−F)dv。仅高斯Doppler核心，未含Voigt自然阻尼翼；高柱密度DLA不适用，Wobs=(1+z)Wrest。'};};
const forestNormCache=new Map();
function forestRawDensity(x,contrast){return Math.exp(contrast*(.7*Math.sin(TAU*x/100)+.35*Math.cos(TAU*x/37)+.2*Math.sin(TAU*x/11)));}
function forestDensityMean(contrast){if(!forestNormCache.has(contrast)){if(forestNormCache.size>256)forestNormCache.clear();forestNormCache.set(contrast,simpson(x=>forestRawDensity(x,contrast),0,100,4096)/100);}return forestNormCache.get(contrast);}
function forestDensity(x,contrast){return forestRawDensity(x,contrast)/forestDensityMean(contrast);}
models.forest=p=>{const q=2-.7*(p.gamma-1),D=x=>forestDensity(x,p.contrast),tau=x=>p.A*D(x)**q,F=x=>Math.exp(-tau(x)),mean=simpson(F,0,100,1024),av=simpson(tau,0,100,1024)/100;return {curves:[series('合成透射谱',grid(0,100,F,501))],xLabel:'合成视线坐标（任意长度）',yLabel:'F=e⁻ᵗᵃᵘ',values:[mean/100,-Math.log(mean/100),av],summary:`T∝Δ^(γeff−1)，τ=AΔ^q，q=${q.toFixed(3)}。正合成密度按0–100视线窗口的积分均值归一，使⟨Δ⟩=1；ρ̄指该窗口平均密度。未拟合观测，未加热展宽、速度畸变和屏蔽；不能当作流体模拟或真实类星体谱。`};};
function absorptionDistance(z,Om){return (1+z)**2/Math.sqrt(Om*(1+z)**3+1-Om);}
models.incidence=p=>{const factor=(P.c/1e5)/70*p.n*Math.PI*(p.R/1000)**2,fn=z=>factor*absorptionDistance(z,p.Om),X=simpson(z=>absorptionDistance(z,p.Om),0,p.z,1024);return {curves:[series('固定共动数量与物理截面的dN/dz',grid(0,6,fn)),series('恒定 dN/dX',grid(0,6,()=>factor))],point:{x:p.z,y:fn(p.z)},xLabel:'红移 z',yLabel:'路径发生率（每单位z或X）',values:[fn(p.z),factor,X],summary:'H₀=70km/s/Mpc，平坦ΛCDM无辐射，ncom固定、σproper=πR²固定。无演化对应常dN/dX，而非常dN/dz；X为无量纲吸收距离，不是实际空间长度。'};};
models.lymanLimit=p=>{const N=10**p.N,fn=l=>l<=912?Math.exp(-N/1.6e17*(l/912)**3):1,type=N>=2e20?'DLA（亦属于LLS）':N>=1.6e17?'Lyman-limit系统':'边缘光深小于1';return {curves:[series('中性氢束缚—自由屏透射',grid(600,911.99,fn,201).concat([{x:912,y:fn(912)},{x:912,y:1}],grid(912.01,1100,fn,100)))],xLabel:'静止系波长（Å）',yLabel:'归一化透射',values:[N/1.6e17,912*(1+p.z),type],summary:'τLL=(NHI/1.6×10¹⁷)(λ/912Å)³，仅λ≤912Å。独立纯氢屏，无再发射；图不计算Lyα阻尼翼。LLS与DLA按柱密度有包含关系，非互斥三类。'};};
function neutralCensus(N,X){const H0=70*1e5/(1e6*P.pc),rho=3*H0*H0/(8*Math.PI*P.G);return H0*P.mp/(P.c*rho)*N/X;}
models.census=p=>{const total=10**p.column*p.count,omega=neutralCensus(total,p.X);return {curves:[series('合成目录 ΩHI 随路径',grid(5,100,X=>neutralCensus(total,X)))],point:{x:p.X,y:omega},xLabel:'总吸收距离 ΔX',yLabel:'ΩHI（不含He）',values:[omega,1.3*omega,total],validation:1.3*omega>.048?{level:'caution',message:'含氦气体量超过额外指定的Ωb=0.048参考预算；这组合成目录与路径不能当作该参考宇宙的总体平均。'}:null,summary:'合成目录由相同NHI的count个系统组成，ΣN/ΔX按吸收距离而非红移归一。ΩHI采用当前临界密度、H₀=70；1.3为明确指定的He修正示例；预算诊断额外采用Ωb=0.048作为教学参照，不是从该合成目录测得。不含分子/电离气体、完备性或尘埃选择修正。'};};
function metalThermometer(bH,bM,A){const T=(bH*bH-bM*bM)*1e10/(2*P.k/P.mp*(1-1/A)),turb2=bH*bH-2*P.k*T/P.mp/1e10;return {T,turb2,valid:T>=0&&turb2>=-1e-9};}
models.metal=p=>{const v=metalThermometer(p.H,p.metal,p.A),maxT=p.H*p.H*1e10*P.mp/(2*P.k),fn=T=>Math.sqrt(Math.max(0,p.H*p.H-2*P.k*T/P.mp/1e10*(1-1/p.A)));return {curves:[series('固定氢线宽的同相热+湍流解',grid(0,maxT,fn))],point:v.valid?{x:v.T,y:p.metal}:undefined,xLabel:'温度 T（K）',yLabel:'同相金属线宽 \\(b_m\\)（km/s）',values:[v.T,v.turb2>=0?Math.sqrt(v.turb2):'负的湍流平方',v.valid?'满足同相非负解':'同相模型无物理解'],summary:'bH²=2kBT/mp+bturb²，bm²=2kBT/(A mp)+bturb²。两条线必须来自同一相，负温度或负湍流平方直接标为假设不相容；线宽本身不确定丰度或电离修正。'};};

const lineCache=new Map();
function lineMeasurement(logN,T,turb){const key=logN+':'+T+':'+turb;if(lineCache.has(key))return lineCache.get(key);const v=R.lyalpha(10**logN,T,turb),W=v.equivalentWidth(),WG=2*1215.67/(P.c/1e5)*v.b*R.integrate(u=>-Math.expm1(-v.pref*Math.exp(-u*u)),0,12,1e-9),out={v,W,WG};if(lineCache.size>1024)lineCache.clear();lineCache.set(key,out);return out;}
function wingGrid(width,b,fn){const n=160,lim=Math.log1p(width/b),xs=Array.from({length:n+1},(_,i)=>b*Math.expm1(lim*i/n));return xs.slice(1).reverse().map(x=>({x:-x,y:fn(-x)})).concat(xs.map(x=>({x,y:fn(x)})));}
models.line=p=>{const {v,W}=lineMeasurement(p.N,p.T,p.turb),width=Math.max(10**p.window,3*v.b*Math.sqrt(v.K));return {curves:[series('Voigt：热+湍流卷积自然宽度',wingGrid(width,v.b,v.flux)),series('同原子参数的纯Doppler对照',wingGrid(width,v.b,v.gaussian))],xLabel:'相对线心速度（km/s）',yLabel:'归一化透射 F',yDomain:[0,1.04],values:[v.b,v.a,W],summary:'真实Voigt卷积：Faddeeva有理展开配合远翼渐近式；NIST未分辨Lyα参数λ=1215.67Å、f=0.4162、A=6.265×10⁸s⁻¹。W独立积分到绘图区之外并补解析尾；画幅±'+width.toFixed(0)+'km/s；显示半宽取控件下限与阻尼翼特征尺度的较大值。未含多云、碰撞宽化、仪器响应与连续谱误差。'};};
models.growthCurve=p=>{const probe=lineMeasurement(p.N,p.T,p.turb),data=gridAt(11,21.5,N=>lineMeasurement(N,p.T,p.turb).W,[p.N],85),doppler=gridAt(11,21.5,N=>lineMeasurement(N,p.T,p.turb).WG,[p.N],85),slope=(Math.log(lineMeasurement(p.N+.01,p.T,p.turb).W)-Math.log(lineMeasurement(p.N-.01,p.T,p.turb).W))/(.02*Math.LN10);return {curves:[series('完整Voigt生长曲线',data),series('纯Doppler核心',doppler)],point:{x:p.N,y:probe.W},xLabel:'log₁₀ NHI / cm⁻²',yLabel:'静止系 W（Å）',yLog:true,values:[probe.W,probe.WG,slope],summary:'弱线W∝N，核心饱和后增长变慢，强阻尼翼渐近W∝N¹ᐟ²。两条线使用同一原子参数，不拼接经验幂律。数值积分采用对数速度变量、远尾补偿；Wobs=(1+z)Wrest，未加入仪器和多云结构。'};};
let qa=.5,qb=1.5;for(let i=0;i<80;i++){const l=qa+(qb-qa)/3,r=qb-(qb-qa)/3;if(l*R.reduction(l*l)>r*R.reduction(r*r))qb=r;else qa=l;}const stellarPeak=(qa+qb)/2;
models.stellarResponse=p=>{const factor=2*Math.PI*Gpc*p.Sigma/(p.sigma*p.kappa/1000),stars=q=>factor*q*R.reduction(q*q),gas=q=>factor*q/(1+q*q),maximum=stars(stellarPeak);return {curves:[series('无碰撞恒星：零频响应',gridAt(0,5,stars,[stellarPeak],251)),series('同Σ、κ且cs=σR的流体对照',gridAt(0,5,gas,[stellarPeak],251)),series('中性阈值1',grid(0,5,()=>1))],point:{x:stellarPeak,y:maximum},xLabel:'q = |k| σR / κ',yLabel:'零频自引力响应（非增长率）',values:[p.sigma*(p.kappa/1000)/(3.36*Gpc*p.Sigma),maximum,2*Math.PI*p.sigma/(p.kappa/1000*stellarPeak)],summary:(maximum>1?'存在响应超过1的局部轴对称不稳定波数。':'零频响应未超过1，此局部轴对称模型无不稳定波段。')+' Schwarzschild速度分布、无限薄、WKB、小扰动；F(0,χ)=(1−e⁻χI₀χ)/χ由缩放Bessel计算，临界系数数值求得3.35828≈3.36。未求复数频率或全局棒。'};};
models.causalFront=p=>{const Q=10**p.Q,n=10**p.n,C=p.C,end=30,fn=t=>R.causalFront(Q,n,C,t*P.Myr),v=fn(p.time);return {curves:[series('有限c、源参考系时间',gridAt(0,end,t=>fn(t).R/(1e6*P.pc),earlyGrid(end,[p.time]),201)),series('c→∞的非相对论对照',gridAt(0,end,t=>fn(t).Rnr/(1e6*P.pc),earlyGrid(end,[p.time]),201))],point:{x:p.time,y:v.R/(1e6*P.pc)},xLabel:'源开启后的源系时间（Myr）',yLabel:'电离前沿半径（Mpc）',values:[v.R/(1e6*P.pc),v.speed/P.c,v.retarded/P.Myr],scene:{kind:'front',ratio:v.Rnr>0?v.R/v.Rnr:0},summary:'由w=q y¹ᐟ³−ln(1−y)单调求根，y=(R/RS)³、q=RS/(c trec)，前沿R≤ct且v≤c。新增Shapiro等(2006)均匀恒定源特例；无关灯、宇宙膨胀或流体膨胀，也不等于观测光锥中的表观泡形状。'};};

function evaluate(id,p){
 if(!models[id])throw new Error('Unknown physical model: '+id);const result=models[id](p),point=result.point;
 // The selected value is computed analytically by the same model. Include it as
 // a drawing node instead of leaving a straight chord across a curved function.
 // In ram stripping the marker belongs to the horizontal applied pressure,
 // including the case where the formal crossing is clamped to zero radius.
 if(point&&Number.isFinite(point.x)&&Number.isFinite(point.y)){
  const curve=result.curves[id==='ram'?1:0];
  if(curve&&!curve.data.some(d=>d.x===point.x&&d.y===point.y)){
   curve.data.push({x:point.x,y:point.y});curve.data.sort((a,b)=>a.x-b.x);
  }
 }
 return result;
}
